package com.asmj.marketplace.complaints;
import java.time.Instant; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document;
@Document(collection="order_complaints")
public class OrderComplaint {
 public enum Status { OPEN, UNDER_REVIEW, WAITING_FOR_CUSTOMER, RESOLVED, REJECTED }
 @Id private String id; @Indexed private String orderId; private String orderNumber; @Indexed private String customerUserId; @Indexed private String vendorUserId; private String customerName; private String subject; private String description; private Status status=Status.OPEN; private String adminNote; private String vendorResponse; private Instant createdAt=Instant.now(); private Instant updatedAt=Instant.now();
 public String getId(){return id;} public void setId(String v){id=v;} public String getOrderId(){return orderId;} public void setOrderId(String v){orderId=v;} public String getOrderNumber(){return orderNumber;} public void setOrderNumber(String v){orderNumber=v;} public String getCustomerUserId(){return customerUserId;} public void setCustomerUserId(String v){customerUserId=v;} public String getVendorUserId(){return vendorUserId;} public void setVendorUserId(String v){vendorUserId=v;} public String getCustomerName(){return customerName;} public void setCustomerName(String v){customerName=v;} public String getSubject(){return subject;} public void setSubject(String v){subject=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public Status getStatus(){return status;} public void setStatus(Status v){status=v;} public String getAdminNote(){return adminNote;} public void setAdminNote(String v){adminNote=v;} public String getVendorResponse(){return vendorResponse;} public void setVendorResponse(String v){vendorResponse=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;}
}
